const SW = `
const CACHE_NAME = 'math-quest-c0dbed0f';
self.addEventListener('install', (e) => {
  self.skipWaiting();
});
self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))
      .then(() => clients.claim())
  );
});
self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET') return;
  if (new URL(e.request.url).pathname.indexOf('/api/') === 0) return;
  e.respondWith(
    fetch(e.request)
      .then((res) => {
        const copy = res.clone();
        caches.open(CACHE_NAME).then((c) => c.put(e.request, copy)).catch(() => {});
        return res;
      })
      .catch(() => caches.match(e.request))
  );
});
`;

// =====================================================================
//  OPTIONAL ACCOUNTS  (needs a KV namespace bound as MATH_KV; without it the
//  game works exactly as before and the Account section explains it is off)
//  Players and parents are separate kinds of account: the same code runs for both, with
//  different key prefixes (KID_NS / PARENT_NS), so a parent's token can never act as a player.
// =====================================================================
const PBKDF2_ITERS = 100000;          // Workers' maximum; stored per account so it can be changed later
const SESSION_TTL = 60 * 60 * 24 * 30; // stay signed in for 30 days
const MAX_SAVE_BYTES = ECON.save.hardLimitBytes;
const NAME_RE = /^[a-z0-9_-]{3,20}$/;
const KID_NS = { acct: 'acct:', sess: 'sess:', fail: 'fail:', noun: 'player name' };
const PARENT_NS = { acct: 'pacct:', sess: 'psess:', fail: 'pfail:', noun: 'parent name' };

function rand(n) { const a = new Uint8Array(n); crypto.getRandomValues(a); return a; }
function toB64(buf) {
  const bytes = new Uint8Array(buf);
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function fromB64(s) {
  const bin = atob(s);
  const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return a;
}
function randomId(bytes) { return toB64(rand(bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
async function hashPassword(pw, salt, iters) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: salt, iterations: iters }, key, 256);
  return toB64(bits);
}
async function sha256Hex(str) {
  const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
  return Array.from(new Uint8Array(d)).map(function (b) { return b.toString(16).padStart(2, '0'); }).join('');
}
function safeEq(a, b) {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
function json(obj, status) {
  return new Response(JSON.stringify(obj), {
    status: status || 200,
    headers: { 'content-type': 'application/json;charset=UTF-8', 'cache-control': 'no-store' }
  });
}
function validState(s) {
  return !!s && typeof s === 'object' && !Array.isArray(s) && Array.isArray(s.unlockedPets) && typeof s.gems === 'number';
}
async function newSession(kv, name, ns) {
  const token = randomId(32);
  await kv.put((ns || KID_NS).sess + await sha256Hex(token), JSON.stringify({ name: name, at: Date.now() }), { expirationTtl: SESSION_TTL });
  return token;
}
async function authenticate(request, kv, ns) {
  const h = request.headers.get('authorization') || '';
  const m = h.match(/^Bearer\s+(.+)$/i);
  if (!m) return null;
  const rec = await kv.get((ns || KID_NS).sess + await sha256Hex(m[1]), 'json');
  if (!rec || !rec.name) return null;
  if (ns === PARENT_NS) {
    // a deleted parent's sign-ins on other devices must not carry over to a new account that reuses the name
    const a = await kv.get(ns.acct + rec.name, 'json');
    if (!a || a.created > rec.at) return null;
  }
  return { name: rec.name, tokenHash: await sha256Hex(m[1]) };
}
async function checkPassword(kv, name, password, ns) {
  const acct = await kv.get((ns || KID_NS).acct + name, 'json');
  if (!acct) return false;
  const h = await hashPassword(password, fromB64(acct.salt), acct.iters || PBKDF2_ITERS);
  return safeEq(h, acct.hash);
}
// Validates a name and password and stores the new account. Returns { name } or { res } (an error response to send).
async function createAccount(kv, ns, body) {
  const name = String(body.name || '').trim().toLowerCase();
  const password = String(body.password || '');
  if (!NAME_RE.test(name)) return { res: json({ error: ns.noun.charAt(0).toUpperCase() + ns.noun.slice(1) + 's are 3-20 letters, numbers, - or _.' }, 400) };
  if (password.length < 6 || password.length > 100) return { res: json({ error: 'Passwords need at least 6 characters.' }, 400) };
  if (await kv.get(ns.acct + name)) return { res: json({ error: 'That ' + ns.noun + ' is taken. Try another!' }, 409) };
  const salt = rand(16);
  const hash = await hashPassword(password, salt, PBKDF2_ITERS);
  await kv.put(ns.acct + name, JSON.stringify({ salt: toB64(salt), hash: hash, iters: PBKDF2_ITERS, created: Date.now() }));
  return { name: name };
}
// Checks a name and password, with a lockout after too many wrong tries. Returns { name } or { res }.
async function signIn(kv, ns, body) {
  const name = String(body.name || '').trim().toLowerCase();
  const password = String(body.password || '');
  const failKey = ns.fail + name;
  const fails = parseInt((await kv.get(failKey)) || '0', 10);
  if (fails >= 8) return { res: json({ error: 'Too many tries. Please wait 15 minutes and try again.' }, 429) };
  if (!NAME_RE.test(name) || !password || !(await checkPassword(kv, name, password, ns))) {
    if (NAME_RE.test(name)) await kv.put(failKey, String(fails + 1), { expirationTtl: 900 });
    return { res: json({ error: 'Wrong ' + ns.noun + ' or password.' }, 401) };
  }
  await kv.delete(failKey);
  return { name: name };
}

// ---------------------------------------------------------------------
//  PARENT ACCOUNTS  (a parent signs in at /parent, claims a child with a code and sees the child's stats)
//  Every key has exactly one writer, so nothing is ever read-modify-written by two people:
//    pacct:<parent>, psess:<hash>, pfail:<parent>   the parent's own login (see PARENT_NS)
//    claim:<hash(code)>   {child, linkId}   written by the CHILD's session; expires after ECON.parents.codeMinutes
//    grant:<child>        {links:[{id, at, primary, ch}]}   written only by the child: the links the child allows
//    plinks:<parent>      {kids:[{child, linkId, at}]}      written only by that parent
//    plink:<linkId>       {parent, at}   written by the parent who used the code (lets the child see who is linked); {gone:true} when that parent stops watching
//    cfail:<parent>       wrong code tries, expires in 15 minutes
//    chall:<child>        {id, problems, minutes, gems, linkId, at}  (or {cancelled:true})  the parent's timed challenge; primary parent only
//    cprog:<child>        {cid, startedAt, count, done, won}         written only by the child: the clock for the challenge (see 16-challenges.js)
//    ctl:<child>          {minGrade, ops, duelsOnline, linkId, at}   the parent's settings; written only by the primary parent and
//                         in force only while that link is still the child's primary link (so unlinking cannot be a way round them)
//    pq:<child>           {linkId, at, qs}   study questions the primary parent added (see 17-study.js); in force under the same rule
//  A parent sees a child only while the child's grant still lists the link, so the child can always unlink from their own device.
//  The first link is the primary parent (the only one who can change settings); later parents can only look.
// ---------------------------------------------------------------------
const CODE_CHARS = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';   // no 0/O/1/I/L: easy to read out loud
const CODE_TTL = 60 * ECON.parents.codeMinutes;
function newLinkCode() {
  return Array.from(rand(8)).map(function (b) { return CODE_CHARS.charAt(b % CODE_CHARS.length); }).join('');
}
function cleanCode(c) {
  const s = String(c || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  return /^[A-Z0-9]{8}$/.test(s) ? s : '';
}
function claimKey(code) { return sha256Hex('claim:' + code).then(function (h) { return 'claim:' + h; }); }

// ---- the child's side (signed in as the player) --------------------------
// A link is live when a parent has used its code (plink exists) or its code has not run out yet.
async function liveLinks(kv, child) {
  const grant = (await kv.get('grant:' + child, 'json')) || { links: [] };
  const used = (await Promise.all(grant.links.map(function (l) { return kv.get('plink:' + l.id, 'json'); }))).map(function (u) { return u && !u.gone ? u : (u ? 'gone' : null); });
  const now = Date.now();
  let changed = false;
  const links = [];
  grant.links.forEach(function (l, i) {
    if (used[i] === 'gone') changed = true;
    else if (used[i] || now - l.at < CODE_TTL * 1000) links.push({ id: l.id, at: l.at, primary: !!l.primary, ch: l.ch, parent: used[i] ? used[i].parent : null });
    else changed = true;
  });
  // if the primary parent went away, the oldest remaining parent takes over
  if (links.length && !links.some(function (l) { return l.primary; })) {
    const next = links.find(function (l) { return l.parent; });
    if (next) { next.primary = true; changed = true; }
  }
  return { links: links, changed: changed };
}
function saveGrant(kv, child, links) {
  return kv.put('grant:' + child, JSON.stringify({ links: links.map(function (l) { return { id: l.id, at: l.at, primary: l.primary, ch: l.ch }; }) }));
}
function linkView(l) { return { id: l.id, at: l.at, primary: l.primary, parent: l.parent, pending: !l.parent }; }

async function handleLink(path, request, kv, who, body) {
  const child = who.name;
  if (path === '/api/link/list' && request.method === 'GET') {
    const cur = await liveLinks(kv, child);
    if (cur.changed) await saveGrant(kv, child, cur.links);
    return json({ links: cur.links.map(linkView) });
  }
  if (path === '/api/link/code' && request.method === 'POST') {
    const cur = await liveLinks(kv, child);
    // a new code replaces any code that has not been used yet
    const pending = cur.links.filter(function (l) { return !l.parent; });
    const links = cur.links.filter(function (l) { return l.parent; });
    for (let i = 0; i < pending.length; i++) await kv.delete(pending[i].ch);
    if (links.length >= ECON.parents.maxLinks) return json({ error: 'This player already has ' + ECON.parents.maxLinks + ' parents linked. Unlink one first.' }, 400);
    const code = newLinkCode();
    const ch = await claimKey(code);
    const link = { id: randomId(6), at: Date.now(), primary: !links.some(function (l) { return l.primary; }), ch: ch, parent: null };
    await kv.put(ch, JSON.stringify({ child: child, linkId: link.id }), { expirationTtl: CODE_TTL });
    links.push(link);
    await saveGrant(kv, child, links);
    return json({ ok: true, code: code, minutes: ECON.parents.codeMinutes, link: linkView(link) });
  }
  if (path === '/api/link/unlink' && request.method === 'POST') {
    const cur = await liveLinks(kv, child);
    const gone = cur.links.find(function (l) { return l.id === body.id; });
    if (!gone) return json({ error: 'That link is already gone.' }, 404);
    await kv.delete(gone.ch);
    const links = cur.links.filter(function (l) { return l !== gone; });
    if (!links.some(function (l) { return l.primary; })) {
      const next = links.find(function (l) { return l.parent; });
      if (next) next.primary = true;
    }
    await saveGrant(kv, child, links);
    return json({ ok: true, links: links.map(linkView) });
  }
  return json({ error: 'Not found' }, 404);
}

// ---- the parent's settings for a child -----------------------------------------
function isPrimaryLink(grant, linkId) { return !!grant && grant.links.some(function (l) { return l.id === linkId && l.primary; }); }
// The settings as the child's device and the parents see them (records written before a field existed read as "not set").
function controlsOf(ctl) {
  return {
    minGrade: ctl.minGrade, ops: ctl.ops, duelsOnline: ctl.duelsOnline,
    goalMinutes: ctl.goalMinutes === undefined ? null : ctl.goalMinutes, goalReward: ctl.goalReward || '',
    adaptive: typeof ctl.adaptive === 'boolean' ? ctl.adaptive : null,
    boost: ctl.boost || {}
  };
}
function liveControls(ctl, grant) {
  return ctl && isPrimaryLink(grant, ctl.linkId) ? controlsOf(ctl) : null;
}
// What the parents have set for a child: { controls, challenge }, each null when absent or no longer from the primary link.
// The common case (nothing set) costs two reads.
async function parentState(kv, child) {
  const first = await Promise.all([kv.get('ctl:' + child, 'json'), kv.get('chall:' + child, 'json')]);
  if (!first[0] && !first[1]) return { controls: null, challenge: null };
  const ids = [first[0], first[1]].filter(Boolean).map(function (x) { return x.linkId; }).filter(function (id, i, a) { return a.indexOf(id) === i; });
  const more = await Promise.all([kv.get('grant:' + child, 'json'), first[1] ? kv.get('cprog:' + child, 'json') : null].concat(ids.map(function (id) { return kv.get('plink:' + id, 'json'); })));
  // a settings record counts while its parent's link is the primary one AND that parent has not stopped watching or left
  const alive = function (id) { const rec = more[2 + ids.indexOf(id)]; return isPrimaryLink(more[0], id) && !(rec && rec.gone); };
  return {
    controls: first[0] && alive(first[0].linkId) ? controlsOf(first[0]) : null,
    challenge: first[1] && alive(first[1].linkId) ? challengeView(first[1], more[1], Date.now()) : null
  };
}
// The parent's own link to a child, when that link is the primary one. Returns { k, grant } or { res }.
async function primaryFor(kv, parent, childName) {
  const mine = (await kv.get('plinks:' + parent, 'json')) || { kids: [] };
  const k = mine.kids.find(function (x) { return x.child === String(childName || ''); });
  if (!k) return { res: json({ error: 'That child is not on your list.' }, 404) };
  const grant = await kv.get('grant:' + k.child, 'json');
  if (!isPrimaryLink(grant, k.linkId)) return { res: json({ error: 'Only the first parent linked to this player can change their settings.' }, 403) };
  return { k: k, grant: grant };
}
// The cloud copy of a save never holds a lower level, or online duels, than the parent allows.
function clampToControls(state, c) {
  if (!c) return;
  if (!(state.grade >= c.minGrade)) state.grade = c.minGrade;
  if (c.duelsOnline === false) state.duelsOnline = false;
}
function cleanControls(b) {
  const minGrade = Number(b.minGrade);
  if (!Number.isInteger(minGrade) || minGrade < 0 || minGrade >= ECON.parents.gradeBands) return null;
  let ops = null;
  if (b.ops !== null && b.ops !== undefined) {
    if (!Array.isArray(b.ops) || b.ops.length < 1 || b.ops.length > 40) return null;
    ops = [];
    for (let i = 0; i < b.ops.length; i++) {
      if (typeof b.ops[i] !== 'string' || !/^[a-z0-9_]{1,20}$/.test(b.ops[i])) return null;
      if (ops.indexOf(b.ops[i]) === -1) ops.push(b.ops[i]);
    }
  }
  if (typeof b.duelsOnline !== 'boolean') return null;
  // the daily time goal and adaptive practice are optional: absent or null means "the player decides"
  let goalMinutes = null;
  if (b.goalMinutes !== null && b.goalMinutes !== undefined) {
    goalMinutes = Number(b.goalMinutes);
    if (!Number.isInteger(goalMinutes) || goalMinutes < ECON.parents.goal.minMinutes || goalMinutes > ECON.parents.goal.maxMinutes) return null;
  }
  const goalReward = b.goalReward === undefined || b.goalReward === null ? '' : b.goalReward;
  if (typeof goalReward !== 'string' || goalReward.length > ECON.parents.goal.maxRewardChars || /[\u0000-\u001f<>]/.test(goalReward)) return null;
  if (b.adaptive !== undefined && b.adaptive !== null && typeof b.adaptive !== 'boolean') return null;
  // extra practice: { math type id: percent of all problems moved to it }
  const boost = {};
  if (b.boost !== undefined && b.boost !== null) {
    const B = ECON.parents.boost;
    if (typeof b.boost !== 'object' || Array.isArray(b.boost)) return null;
    const ids = Object.keys(b.boost);
    let total = 0;
    if (ids.length > B.maxTypes) return null;
    for (let i = 0; i < ids.length; i++) {
      const v = b.boost[ids[i]];
      if (!/^[a-z0-9_]{1,20}$/.test(ids[i]) || !Number.isInteger(v) || v < 0 || v > B.maxPerType) return null;
      if (v) { boost[ids[i]] = v; total += v; }
    }
    if (total > B.maxTotal) return null;
  }
  return { minGrade: minGrade, ops: ops, duelsOnline: b.duelsOnline, goalMinutes: goalMinutes, goalReward: goalReward.trim(), adaptive: typeof b.adaptive === 'boolean' ? b.adaptive : null, boost: boost };
}

// ---- the parent's side ---------------------------------------------------
const SUMMARY_DAYS = 14;
function num(v, max) { return typeof v === 'number' && isFinite(v) ? Math.max(0, Math.min(max || 1e9, v)) : 0; }
// What a parent may see of a child's save: numbers for the report, never the whole save (no PIN hash, no names of friends).
function kidSummary(save) {
  const st = (save && save.state) || {};
  const days = {};
  const src = (st.stats && st.stats.days) || {};
  Object.keys(src).filter(function (k) { return /^\d{4}-\d{2}-\d{2}$/.test(k); }).sort().slice(-SUMMARY_DAYS).forEach(function (k) {
    const d = src[k] || {};
    const ops = {};
    Object.keys(d.ops || {}).slice(0, 40).forEach(function (op) {
      if (/^[a-z0-9_]{1,20}$/.test(op) && Array.isArray(d.ops[op])) ops[op] = [num(d.ops[op][0]), num(d.ops[op][1])];
    });
    // study answers: st = [answered, right], sub = { subject id: [answered, right] }
    const sub = {};
    Object.keys(d.sub || {}).slice(0, 12).forEach(function (id) {
      if (/^[a-z]{1,10}$/.test(id) && Array.isArray(d.sub[id])) sub[id] = [num(d.sub[id][0]), num(d.sub[id][1])];
    });
    days[k] = { s: num(d.s), a: num(d.a), ms: num(d.ms), h: num(d.h), w: num(d.w), ops: ops, st: Array.isArray(d.st) ? [num(d.st[0]), num(d.st[1])] : [0, 0], sub: sub };
  });
  // study questions answered wrong: [question id, times wrong, times right], the most often missed first (at most 40)
  const seen = (st.study && st.study.seen) || {};
  const missed = Object.keys(seen).filter(function (id) { return /^[A-Za-z0-9_-]{3,16}$/.test(id) && Array.isArray(seen[id]) && num(seen[id][1], 1e6) > 0; })
    .map(function (id) { return [id, num(seen[id][1], 1e6), num(seen[id][0], 1e6)]; })
    .sort(function (a, b) { return b[1] - a[1] || a[2] - b[2]; });
  return {
    studyMissed: missed.slice(0, 40), studyMissedCount: missed.length,
    updatedAt: save ? save.updatedAt || 0 : 0,
    grade: num(st.grade, 12),
    gems: num(st.gems),
    streak: num(st.streakCal && st.streakCal.count),
    raids: num(st.raidsCleared),
    trophies: num(st.tour && st.tour.trophies),
    duelsOnline: st.duelsOnline !== false,
    days: days
  };
}

async function handleParent(path, request, kv, body) {
  if (path === '/api/parent/register' && request.method === 'POST') {
    const r = await createAccount(kv, PARENT_NS, body);
    if (r.res) return r.res;
    return json({ ok: true, name: r.name, token: await newSession(kv, r.name, PARENT_NS) });
  }
  if (path === '/api/parent/login' && request.method === 'POST') {
    const r = await signIn(kv, PARENT_NS, body);
    if (r.res) return r.res;
    return json({ ok: true, name: r.name, token: await newSession(kv, r.name, PARENT_NS) });
  }
  const who = await authenticate(request, kv, PARENT_NS);
  if (!who) return json({ error: 'Please sign in again.' }, 401);
  const parent = who.name;

  if (path === '/api/parent/kids' && request.method === 'GET') {
    const mine = (await kv.get('plinks:' + parent, 'json')) || { kids: [] };
    const rows = await Promise.all(mine.kids.map(async function (k) {
      const reads = await Promise.all([kv.get('grant:' + k.child, 'json'), kv.get('save:' + k.child, 'json'), kv.get('ctl:' + k.child, 'json'), kv.get('chall:' + k.child, 'json'), kv.get('cprog:' + k.child, 'json')]);
      const link = reads[0] && reads[0].links.find(function (l) { return l.id === k.linkId; });
      if (!link) return { child: k.child, revoked: true };
      const challenge = reads[3] && isPrimaryLink(reads[0], reads[3].linkId) ? challengeView(reads[3], reads[4], Date.now()) : null;
      return Object.assign({ child: k.child, primary: !!link.primary, revoked: false, controls: liveControls(reads[2], reads[0]), challenge: challenge }, kidSummary(reads[1]));
    }));
    return json({ kids: rows });
  }

  if (path === '/api/parent/claim' && request.method === 'POST') {
    const failKey = 'cfail:' + parent;
    const fails = parseInt((await kv.get(failKey)) || '0', 10);
    if (fails >= ECON.parents.codeTries) return json({ error: 'Too many wrong codes. Please wait 15 minutes and try again.' }, 429);
    const wrong = async function () { await kv.put(failKey, String(fails + 1), { expirationTtl: 900 }); return json({ error: 'That code is not right, or it ran out. Ask for a new one on the child\'s device.' }, 404); };
    const code = cleanCode(body.code);
    if (!code) return wrong();
    const key = await claimKey(code);
    const claim = await kv.get(key, 'json');
    if (!claim) return wrong();
    const grant = await kv.get('grant:' + claim.child, 'json');
    if (!grant || !grant.links.some(function (l) { return l.id === claim.linkId; })) return wrong();
    const mine = (await kv.get('plinks:' + parent, 'json')) || { kids: [] };
    const kids = mine.kids.filter(function (k) { return k.child !== claim.child; });
    if (kids.length >= ECON.parents.maxKids) return json({ error: 'You are already watching ' + ECON.parents.maxKids + ' children.' }, 400);
    kids.push({ child: claim.child, linkId: claim.linkId, at: Date.now() });
    await kv.put('plink:' + claim.linkId, JSON.stringify({ parent: parent, at: Date.now() }));
    await kv.put('plinks:' + parent, JSON.stringify({ kids: kids }));
    await kv.delete(key);
    await kv.delete(failKey);
    return json({ ok: true, child: claim.child });
  }

  if (path === '/api/parent/controls' && request.method === 'POST') {
    const p = await primaryFor(kv, parent, body.child);
    if (p.res) return p.res;
    const c = cleanControls(body);
    if (!c) return json({ error: 'Those settings are not valid.' }, 400);
    await kv.put('ctl:' + p.k.child, JSON.stringify(Object.assign({ linkId: p.k.linkId, at: Date.now() }, c)));
    return json({ ok: true, controls: c });
  }

  if (path === '/api/parent/challenge' && request.method === 'POST') return setChallenge(kv, parent, body);

  if (path.indexOf('/api/parent/study/') === 0 && request.method === 'POST') return handleParentStudy(path, kv, parent, body);

  if (path === '/api/parent/delete' && request.method === 'POST') {
    if (!(await checkPassword(kv, parent, String(body.password || ''), PARENT_NS))) return json({ error: 'Wrong password.' }, 401);
    const mine = (await kv.get('plinks:' + parent, 'json')) || { kids: [] };
    for (let i = 0; i < mine.kids.length; i++) {
      const k = mine.kids[i];
      // tell the child the link ended, and remove what this parent wrote for them
      await kv.put('plink:' + k.linkId, JSON.stringify({ gone: true }), { expirationTtl: CODE_TTL });
      const rows = await Promise.all([kv.get('ctl:' + k.child, 'json'), kv.get('chall:' + k.child, 'json'), kv.get('pq:' + k.child, 'json')]);
      if (rows[0] && rows[0].linkId === k.linkId) await kv.delete('ctl:' + k.child);
      if (rows[1] && rows[1].linkId === k.linkId) await kv.delete('chall:' + k.child);
      if (rows[2] && rows[2].linkId === k.linkId) await kv.delete('pq:' + k.child);
    }
    await Promise.all(['plinks:' + parent, 'cfail:' + parent, PARENT_NS.acct + parent, PARENT_NS.fail + parent, PARENT_NS.sess + who.tokenHash].map(function (key) { return kv.delete(key); }));
    return json({ ok: true });
  }

  if (path === '/api/parent/unlink' && request.method === 'POST') {
    const mine = (await kv.get('plinks:' + parent, 'json')) || { kids: [] };
    const gone = mine.kids.find(function (k) { return k.child === String(body.child || ''); });
    if (!gone) return json({ error: 'That child is not on your list.' }, 404);
    await kv.put('plinks:' + parent, JSON.stringify({ kids: mine.kids.filter(function (k) { return k !== gone; }) }));
    await kv.put('plink:' + gone.linkId, JSON.stringify({ gone: true }), { expirationTtl: CODE_TTL });   // tells the child this link ended (the marker fades once the child has tidied up)
    return json({ ok: true });
  }

  return json({ error: 'Not found' }, 404);
}

// ---------------------------------------------------------------------
//  TIMED CHALLENGES  (a parent sets "N correct answers in M minutes"; finishing in time pays N gems)
//  The parent writes chall:<child> (see 15-parents.js); the child writes cprog:<child>. The clock is the server's:
//  it starts when the child taps Start, and a win is accepted only if it arrives inside the time and not faster than
//  ECON.parents.challenge.minSecPerProblem per answer. All-or-nothing: running out of time costs nothing.
//  The answers themselves are checked on the child's device (like all practice), so the limits above are what keep a
//  claim believable. The gems are added by the child's device, once per challenge id (the server reports it as won
//  as many times as asked, so a lost reply can be recovered).
// ---------------------------------------------------------------------
const CHAL = ECON.parents.challenge;

// What either side may see of a challenge: its numbers and where it stands.
// state: 'ready' (not started), 'running', 'won' or 'ended' (time ran out).
function challengeView(def, prog, now) {
  if (!def || def.cancelled) return null;
  const v = { id: def.id, problems: def.problems, minutes: def.minutes, gems: def.gems, state: 'ready', count: 0, startedAt: 0, endsAt: 0, serverNow: now };
  const p = prog && prog.cid === def.id ? prog : null;
  if (!p) return v;
  v.startedAt = p.startedAt;
  v.endsAt = p.startedAt + def.minutes * 60000;
  v.count = Math.min(def.problems, p.count || 0);
  if (p.done) v.state = p.won ? 'won' : 'ended';
  else if (now > v.endsAt + CHAL.graceSeconds * 1000) v.state = 'ended';
  else v.state = 'running';
  return v;
}
function challengeBusy(v) { return !!v && (v.state === 'ready' || v.state === 'running'); }

// ---- the parent starts or cancels one ---------------------------------------
async function setChallenge(kv, parent, body) {
  const p = await primaryFor(kv, parent, body.child);
  if (p.res) return p.res;
  const child = p.k.child;
  const reads = await Promise.all([kv.get('chall:' + child, 'json'), kv.get('cprog:' + child, 'json')]);
  const view = reads[0] && isPrimaryLink(p.grant, reads[0].linkId) ? challengeView(reads[0], reads[1], Date.now()) : null;
  if (body.cancel === true) {
    if (!view) return json({ error: 'There is no challenge to cancel.' }, 404);
    await kv.put('chall:' + child, JSON.stringify({ id: view.id, cancelled: true, linkId: p.k.linkId, at: Date.now() }));
    return json({ ok: true, challenge: null });
  }
  const problems = Number(body.problems), minutes = Number(body.minutes);
  const gemsPer = body.gemsPer === undefined || body.gemsPer === null ? CHAL.gemPerProblem : Number(body.gemsPer);
  if (!Number.isInteger(problems) || problems < 1 || problems > CHAL.maxProblems) return json({ error: 'Pick 1 to ' + CHAL.maxProblems + ' problems.' }, 400);
  if (!Number.isInteger(minutes) || minutes < CHAL.minMinutes || minutes > CHAL.maxMinutes) return json({ error: 'Pick ' + CHAL.minMinutes + ' to ' + CHAL.maxMinutes + ' minutes.' }, 400);
  if (!Number.isInteger(gemsPer) || gemsPer < 1 || gemsPer > CHAL.maxGemPerProblem) return json({ error: 'Pick 1 to ' + CHAL.maxGemPerProblem + ' gems per answer.' }, 400);
  if (problems * gemsPer > CHAL.maxGems) return json({ error: 'That would be ' + problems * gemsPer + ' gems. The most for one challenge is ' + CHAL.maxGems + '.' }, 400);
  if (challengeBusy(view)) return json({ error: 'A challenge is already going. Cancel it first.' }, 409);
  const def = { id: randomId(6), problems: problems, minutes: minutes, gems: problems * gemsPer, linkId: p.k.linkId, at: Date.now() };
  await kv.put('chall:' + child, JSON.stringify(def));
  return json({ ok: true, challenge: challengeView(def, null, Date.now()) });
}

// ---- the child's side ---------------------------------------------------------
async function handleChallenge(path, request, kv, who, body) {
  const child = who.name;
  const st = await parentState(kv, child);
  const view = st.challenge;
  if (!view || view.id !== body.id) return json({ error: 'That challenge is over or was cancelled.', challenge: view }, 404);
  const now = Date.now();
  const prog = await kv.get('cprog:' + child, 'json');
  const mine = prog && prog.cid === view.id ? prog : null;
  const save = function (p) { return kv.put('cprog:' + child, JSON.stringify(p), { expirationTtl: 60 * 60 * 24 * 30 }); };
  const def = { id: view.id, problems: view.problems, minutes: view.minutes, gems: view.gems };

  if (path === '/api/challenge/start' && request.method === 'POST') {
    const cur = mine || { cid: view.id, startedAt: now, count: 0, done: false, won: false };
    if (!mine) await save(cur);   // asking again never restarts the clock
    return json({ ok: true, challenge: challengeView(def, cur, now) });
  }
  if (!mine) return json({ error: 'Start the challenge first.' }, 400);
  const elapsed = now - mine.startedAt;

  if (path === '/api/challenge/progress' && request.method === 'POST') {
    if (view.state === 'running') {
      const believable = Math.floor(elapsed / 1000 / CHAL.minSecPerProblem) + 1;
      const count = Math.max(mine.count, Math.min(Math.floor(Number(body.count)) || 0, def.problems, believable));
      if (count !== mine.count) { mine.count = count; await save(mine); }
    }
    return json({ ok: true, challenge: challengeView(def, mine, now) });
  }

  if (path === '/api/challenge/claim' && request.method === 'POST') {
    if (mine.done) return json({ ok: true, won: !!mine.won, gems: mine.won ? def.gems : 0, challenge: challengeView(def, mine, now) });
    if (view.state === 'ended') {
      mine.done = true; mine.won = false;
      await save(mine);
      return json({ ok: true, won: false, gems: 0, challenge: challengeView(def, mine, now) });
    }
    if (!(Number(body.count) >= def.problems)) return json({ error: 'Not finished yet.' }, 400);
    if (elapsed < def.problems * CHAL.minSecPerProblem * 1000) return json({ error: 'That was too fast to be real. Keep going and try again.' }, 400);
    mine.done = true; mine.won = true; mine.count = def.problems;
    await save(mine);
    return json({ ok: true, won: true, gems: def.gems, challenge: challengeView(def, mine, now) });
  }
  return json({ error: 'Not found' }, 404);
}

// ---------------------------------------------------------------------
//  STUDY QUESTIONS A PARENT ADDS  (the child's Study screen mixes them in with the built-in questions)
//    pq:<child>   {linkId, at, only, qs:[{id, s, q, a, alt, wrong}]}   (only: show just these, hide the built-in questions)   written only by the primary parent, like ctl:
//  The questions count only while that link is still the child's primary link and the parent has not stopped watching, so unlinking
//  cannot leave a parent's questions behind. They reach only the parent's own child: they are never used in duels, tournaments or the vault.
// ---------------------------------------------------------------------
async function liveStudy(kv, child) {
  const pq = await kv.get('pq:' + child, 'json');
  if (!pq || !Array.isArray(pq.qs)) return { questions: [], only: false };
  const rows = await Promise.all([kv.get('grant:' + child, 'json'), kv.get('plink:' + pq.linkId, 'json')]);
  return isPrimaryLink(rows[0], pq.linkId) && !(rows[1] && rows[1].gone) ? { questions: pq.qs, only: pq.only === true } : { questions: [], only: false };
}
// The children (from the names asked for) that this parent is the primary parent of: [{ child, linkId }].
async function primaryKids(kv, parent, names) {
  const mine = (await kv.get('plinks:' + parent, 'json')) || { kids: [] };
  const want = (Array.isArray(names) ? names : []).filter(function (n, i, a) { return typeof n === 'string' && a.indexOf(n) === i; }).slice(0, ECON.parents.maxKids);
  const kids = mine.kids.filter(function (k) { return want.indexOf(k.child) !== -1; });
  const grants = await Promise.all(kids.map(function (k) { return kv.get('grant:' + k.child, 'json'); }));
  return kids.filter(function (k, i) { return isPrimaryLink(grants[i], k.linkId); });
}
async function handleParentStudy(path, kv, parent, body) {
  const kids = await primaryKids(kv, parent, body.children || [body.child]);
  if (!kids.length) return json({ error: 'You can only change study questions for children you are the first parent of.' }, 403);
  const L = ECON.study.parent;
  const record = async function (k) {
    const pq = await kv.get('pq:' + k.child, 'json');
    return pq && pq.linkId === k.linkId && Array.isArray(pq.qs) ? pq : { qs: [], only: false };
  };
  const current = async function (k) { return (await record(k)).qs; };
  const save = async function (k, qs, only) {
    await kv.put('pq:' + k.child, JSON.stringify({ linkId: k.linkId, at: Date.now(), only: only === undefined ? (await record(k)).only === true : only, qs: qs }));
  };

  if (path === '/api/parent/study/list') {
    const lists = {}, only = {};
    for (let i = 0; i < kids.length; i++) { const rec = await record(kids[i]); lists[kids[i].child] = rec.qs; only[kids[i].child] = rec.only === true; }
    return json({ ok: true, lists: lists, only: only });
  }
  // "Only my questions": the child's Study screen then shows just the parent's questions (when there are any), not the built-in ones.
  if (path === '/api/parent/study/only') {
    if (typeof body.only !== 'boolean') return json({ error: 'Choose on or off.' }, 400);
    const results = {};
    for (let i = 0; i < kids.length; i++) { await save(kids[i], await current(kids[i]), body.only); results[kids[i].child] = { only: body.only }; }
    return json({ ok: true, results: results });
  }
  if (path === '/api/parent/study/add') {
    if (!Array.isArray(body.questions) || !body.questions.length || body.questions.length > L.bulk) return json({ error: 'Add between 1 and ' + L.bulk + ' questions at a time.' }, 400);
    const clean = [];
    for (let i = 0; i < body.questions.length; i++) {
      const c = cleanStudyQ(body.questions[i]);
      if (!c) return json({ error: 'Question ' + (i + 1) + ' is not valid. It needs a question (up to ' + L.qMax + ' letters) and an answer (up to ' + L.aMax + ').' }, 400);
      clean.push(c);
    }
    const results = {};
    for (let i = 0; i < kids.length; i++) {
      const k = kids[i], qs = await current(k);
      const have = qs.map(function (x) { return x.q.toLowerCase(); });
      let added = 0, dup = 0, full = 0;
      clean.forEach(function (c) {
        if (have.indexOf(c.q.toLowerCase()) !== -1) dup++;
        else if (qs.length >= L.max) full++;
        else { qs.push(Object.assign({ id: 'p' + randomId(4) }, c)); have.push(c.q.toLowerCase()); added++; }
      });
      if (added) await save(k, qs);
      results[k.child] = { added: added, dup: dup, full: full, total: qs.length };
    }
    return json({ ok: true, results: results });
  }
  if (path === '/api/parent/study/remove') {
    const ids = Array.isArray(body.ids) ? body.ids.filter(function (x) { return typeof x === 'string'; }).slice(0, L.max) : [];
    if (!ids.length && body.all !== true) return json({ error: 'Nothing to remove.' }, 400);
    const results = {};
    for (let i = 0; i < kids.length; i++) {
      const k = kids[i], qs = await current(k);
      const keep = body.all === true ? [] : qs.filter(function (x) { return ids.indexOf(x.id) === -1; });
      if (keep.length !== qs.length) await save(k, keep);
      results[k.child] = { removed: qs.length - keep.length, total: keep.length };
    }
    return json({ ok: true, results: results });
  }
  return json({ error: 'Not found' }, 404);
}

// ---------------------------------------------------------------------
//  ONLINE DUELS  (async: same questions, scored on the server, gem stakes)
//  KV layout (every key expires after 3 days):
//    duel:<id>           immutable {from,to,stake,qs:[{e,l,o,a}],created}
//    res:<id>:<name>     written only by that player {score,ms,at}
//    duels:<name>:<id>   index entry (metadata) for each participant
//    ping:<name>         last notification for that player
//    decl:<id>           the invited player declined
//    blk:<me>:<them>     me has blocked them (no expiry)
// ---------------------------------------------------------------------
const DUEL_TTL = 60 * 60 * 24 * ECON.duel.ttlDays;
function newDuelId() { return randomId(6); }
async function savedGems(kv, name) {
  const s = await kv.get('save:' + name, 'json');
  return s && s.state && typeof s.state.gems === 'number' ? s.state.gems : 0;
}
function cleanText(t, max, allowSubSup) {
  if (typeof t !== 'string' || t.length > max) return null;
  const bare = allowSubSup ? t.replace(/<\/?(sub|sup)>/g, '') : t;
  return /[<>&"`]/.test(bare) ? null : t;
}
// Plain text for trivia questions: any characters but control ones. The client always shows it as text (escHtml), never as HTML.
function cleanPlain(t, max) {
  return typeof t === 'string' && t.length >= 1 && t.length <= max && !/[\u0000-\u001f\u007f]/.test(t) ? t : null;
}
function cleanQuestions(qs) {
  if (!Array.isArray(qs) || [5, 10, 15].indexOf(qs.length) === -1) return null;
  const out = [];
  for (let i = 0; i < qs.length; i++) {
    const q = qs[i] || {};
    if (q.t === 't') {                                                   // a trivia (study) question: words, not numbers
      const te = cleanPlain(q.e, 520), ta = cleanPlain(q.a, 120);
      if (!te || !ta || !Array.isArray(q.o) || q.o.length < 2 || q.o.length > 4) return null;
      const to = q.o.map(function (x) { return cleanPlain(x, 120); });
      if (to.some(function (x, k) { return !x || to.indexOf(x) !== k; }) || to.indexOf(ta) === -1) return null;
      out.push({ t: 't', e: te, l: '', o: to, a: ta });
      continue;
    }
    const e = cleanText(q.e, 240, true);
    const l = cleanText(q.l == null ? '=' : q.l, 24, false);
    if (!e || l === null) return null;
    if (!Array.isArray(q.o) || q.o.length < 2 || q.o.length > 4) return null;
    const o = q.o.map(Number);
    const a = Number(q.a);
    if (o.some(function (v) { return !isFinite(v) || Math.abs(v) > 1e9; }) || !isFinite(a)) return null;
    if (!o.some(function (v) { return Math.abs(v - a) < 0.0001; })) return null;
    out.push({ e: e, l: l, o: o, a: a });
  }
  return out;
}
async function duelSummary(kv, duel, me) {
  const opp = duel.from === me ? duel.to : duel.from;
  const rs = await Promise.all([kv.get('res:' + duel.id + ':' + me, 'json'), kv.get('res:' + duel.id + ':' + opp, 'json'), kv.get('decl:' + duel.id)]);
  const mine = rs[0], theirs = rs[1];
  const sum = { id: duel.id, from: duel.from, to: duel.to, opp: opp, stake: duel.stake, n: duel.qs.length, created: duel.created, mine: mine ? { score: mine.score, ms: mine.ms } : null, theirs: null, outcome: null, declined: false };
  if (rs[2]) { sum.declined = true; sum.status = 'declined'; return sum; }
  if (!mine) { sum.status = 'todo'; return sum; }
  if (!theirs) { sum.status = 'waiting'; return sum; }
  sum.status = 'done';
  sum.theirs = { score: theirs.score, ms: theirs.ms };
  sum.outcome = mine.score > theirs.score ? 'win' : (mine.score < theirs.score ? 'loss' : (mine.ms < theirs.ms ? 'win' : (mine.ms > theirs.ms ? 'loss' : 'tie')));
  return sum;
}
async function ping(kv, to, id, kind, from) {
  await kv.put('ping:' + to, JSON.stringify({ t: Date.now(), id: id, k: kind, from: from }), { expirationTtl: DUEL_TTL });
}
async function handleDuel(path, request, url, kv, who, body) {
  const me = who.name;
  if (path === '/api/duel/ping' && request.method === 'GET') {
    return json({ ping: (await kv.get('ping:' + me, 'json')) || null });
  }

  if (path === '/api/duel/list' && request.method === 'GET') {
    const l = await kv.list({ prefix: 'duels:' + me + ':', limit: 60 });
    const metas = l.keys.map(function (k) { return k.metadata; }).filter(function (m) { return m && m.id; });
    metas.sort(function (a, b) { return b.created - a.created; });
    const duels = (await Promise.all(metas.slice(0, 12).map(async function (m) {
      const d = await kv.get('duel:' + m.id, 'json');
      return d ? duelSummary(kv, d, me) : null;
    }))).filter(Boolean);
    return json({ duels: duels });
  }

  if (path === '/api/duel/get' && request.method === 'GET') {
    const id = String(url.searchParams.get('id') || '');
    const d = /^[A-Za-z0-9_-]{6,12}$/.test(id) ? await kv.get('duel:' + id, 'json') : null;
    if (!d || (d.from !== me && d.to !== me)) return json({ error: 'That duel is not available any more.' }, 404);
    const sum = await duelSummary(kv, d, me);
    return json({ duel: { id: d.id, from: d.from, to: d.to, stake: d.stake, qs: d.qs.map(function (q) { return q.t === 't' ? { t: 't', e: q.e, l: q.l, o: q.o } : { e: q.e, l: q.l, o: q.o }; }) }, summary: sum });
  }

  if (path === '/api/duel/create' && request.method === 'POST') {
    const to = String(body.to || '').trim().toLowerCase();
    const stake = Number(body.stake);
    if (!NAME_RE.test(to) || to === me) return json({ error: 'Type the player name of a friend.' }, 400);
    if (ECON.duel.stakes.indexOf(stake) === -1) return json({ error: 'Pick one of the stake choices.' }, 400);
    const qs = cleanQuestions(body.qs);
    if (!qs) return json({ error: 'Those questions were not valid.' }, 400);
    if (!(await kv.get('acct:' + to)) || (await kv.get('blk:' + to + ':' + me))) return json({ error: 'No player called "' + to + '" can be challenged right now.' }, 404);
    const rlKey = 'rl:' + me;
    const used = parseInt((await kv.get(rlKey)) || '0', 10);
    if (used >= ECON.duel.maxPerHour) return json({ error: 'Lots of challenges! Take a short break and try again soon.' }, 429);
    if (stake > 0) {
      const gems = await Promise.all([savedGems(kv, me), savedGems(kv, to)]);
      if (!stakeAllowed(stake, gems[0])) return json({ error: 'You can stake at most half of your gems.' }, 400);
      if (!stakeAllowed(stake, gems[1])) return json({ error: 'That friend cannot cover this stake. Try a smaller one.' }, 400);
    }
    await kv.put(rlKey, String(used + 1), { expirationTtl: 3600 });
    const id = newDuelId();
    const duel = { id: id, from: me, to: to, stake: stake, qs: qs, created: Date.now() };
    const meta = { id: id, created: duel.created };
    await Promise.all([
      kv.put('duel:' + id, JSON.stringify(duel), { expirationTtl: DUEL_TTL }),
      kv.put('duels:' + me + ':' + id, '1', { expirationTtl: DUEL_TTL, metadata: meta }),
      kv.put('duels:' + to + ':' + id, '1', { expirationTtl: DUEL_TTL, metadata: meta })
    ]);
    await ping(kv, to, id, 'invite', me);
    return json({ ok: true, id: id });
  }

  if (path === '/api/duel/submit' && request.method === 'POST') {
    const id = String(body.id || '');
    const d = /^[A-Za-z0-9_-]{6,12}$/.test(id) ? await kv.get('duel:' + id, 'json') : null;
    if (!d || (d.from !== me && d.to !== me)) return json({ error: 'That duel is not available any more.' }, 404);
    if (await kv.get('decl:' + id)) return json({ error: 'That challenge was declined.' }, 409);
    const resKey = 'res:' + id + ':' + me;
    if (!(await kv.get(resKey))) {
      const ans = Array.isArray(body.answers) ? body.answers : [];
      if (ans.length !== d.qs.length) return json({ error: 'Answer every question first.' }, 400);
      let score = 0;
      d.qs.forEach(function (q, i) { if (q.t === 't' ? String(ans[i]) === q.a : Math.abs(Number(ans[i]) - q.a) < 0.0001) score += 1; });
      const ms = Math.min(900000, Math.max(d.qs.length * 400, Math.round(Number(body.ms) || 0)));
      await kv.put(resKey, JSON.stringify({ score: score, ms: ms, at: Date.now() }), { expirationTtl: DUEL_TTL });
      const other = d.from === me ? d.to : d.from;
      // if they have not played yet this is still an invitation ("your turn"); otherwise it is the result
      await ping(kv, other, id, (await kv.get('res:' + id + ':' + other)) ? 'result' : 'invite', me);
    }
    return json({ ok: true, summary: await duelSummary(kv, d, me) });
  }

  if (path === '/api/duel/decline' && request.method === 'POST') {
    const id = String(body.id || '');
    const d = /^[A-Za-z0-9_-]{6,12}$/.test(id) ? await kv.get('duel:' + id, 'json') : null;
    if (!d || d.to !== me) return json({ error: 'That duel is not available any more.' }, 404);
    if (!(await kv.get('res:' + id + ':' + me))) {
      await kv.put('decl:' + id, '1', { expirationTtl: DUEL_TTL });
      await ping(kv, d.from, id, 'declined', me);
    }
    return json({ ok: true });
  }

  if (path === '/api/duel/block' && request.method === 'POST') {
    const name = String(body.name || '').trim().toLowerCase();
    if (!NAME_RE.test(name) || name === me) return json({ error: 'Bad name' }, 400);
    await kv.put('blk:' + me + ':' + name, '1');
    return json({ ok: true });
  }

  return json({ error: 'Not found' }, 404);
}

async function handleApi(request, env, url) {
  const path = url.pathname;
  if (path === '/api/status') return json({ enabled: !!env.MATH_KV });
  const kv = env.MATH_KV;
  if (!kv) return json({ error: 'Online accounts are not set up on this server yet.' }, 501);
  if (request.method !== 'GET' && request.method !== 'POST' && request.method !== 'PUT') return json({ error: 'Method not allowed' }, 405);

  let body = {};
  if (request.method !== 'GET') {
    try {
      const txt = await request.text();
      if (txt.length > MAX_SAVE_BYTES + 5000) return json({ error: 'Too large' }, 413);
      body = txt ? JSON.parse(txt) : {};
    } catch (e) { return json({ error: 'Bad request' }, 400); }
  }

  if (path === '/api/register' && request.method === 'POST') {
    const made = await createAccount(kv, KID_NS, body);
    if (made.res) return made.res;
    const name = made.name;
    let version = 0;
    if (validState(body.state) && JSON.stringify(body.state).length <= MAX_SAVE_BYTES) {
      version = 1;
      await kv.put('save:' + name, JSON.stringify({ state: body.state, version: 1, updatedAt: Date.now() }));
    }
    return json({ ok: true, name: name, token: await newSession(kv, name), version: version });
  }

  if (path === '/api/login' && request.method === 'POST') {
    const r = await signIn(kv, KID_NS, body);
    if (r.res) return r.res;
    const save = await kv.get('save:' + r.name, 'json');
    return json({ ok: true, name: r.name, token: await newSession(kv, r.name), save: save || null, ...(await parentState(kv, r.name)) });
  }

  if (path.indexOf('/api/parent/') === 0) return handleParent(path, request, kv, body);

  const who = await authenticate(request, kv);
  if (!who) return json({ error: 'Please sign in again.' }, 401);

  if (path === '/api/save' && request.method === 'GET') {
    return json({ save: (await kv.get('save:' + who.name, 'json')) || null, ...(await parentState(kv, who.name)) });
  }

  if (path === '/api/save' && request.method === 'PUT') {
    if (!validState(body.state)) return json({ error: 'Invalid save' }, 400);
    if (JSON.stringify(body.state).length > MAX_SAVE_BYTES) return json({ error: 'Save too large' }, 413);
    const cur = await kv.get('save:' + who.name, 'json');
    const curVersion = cur ? cur.version : 0;
    if (!body.force && Number(body.baseVersion) !== curVersion) return json({ conflict: true, save: cur || null }, 409);
    const parents = await parentState(kv, who.name);
    clampToControls(body.state, parents.controls);
    const next = { state: body.state, version: curVersion + 1, updatedAt: Date.now() };
    await kv.put('save:' + who.name, JSON.stringify(next));
    return json({ ok: true, version: next.version, updatedAt: next.updatedAt, ...parents });
  }

  if (path === '/api/study' && request.method === 'GET') return json(await liveStudy(kv, who.name));

  if (path.indexOf('/api/duel/') === 0) return handleDuel(path, request, url, kv, who, body);
  if (path.indexOf('/api/challenge/') === 0) return handleChallenge(path, request, kv, who, body);
  if (path.indexOf('/api/link/') === 0) return handleLink(path, request, kv, who, body);

  if (path === '/api/logout' && request.method === 'POST') {
    await kv.delete('sess:' + who.tokenHash);
    return json({ ok: true });
  }

  if (path === '/api/delete' && request.method === 'POST') {
    if (!(await checkPassword(kv, who.name, String(body.password || '')))) return json({ error: 'Wrong password.' }, 401);
    await kv.delete('acct:' + who.name);
    await kv.delete('save:' + who.name);
    await kv.delete('grant:' + who.name);   // parents lose sight of a deleted account
    await kv.delete('pq:' + who.name);
    await kv.delete('sess:' + who.tokenHash);
    return json({ ok: true });
  }

  return json({ error: 'Not found' }, 404);
}

// Headers added to every response. The page needs inline script/style (it is one self-contained file),
// but nothing may load from, or send data to, any other site.
const SECURITY_HEADERS = {
  'content-security-policy': "upgrade-insecure-requests; default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; manifest-src 'self'; worker-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
  // browsers that reached us over https must keep using https (ignored over http; no includeSubDomains so other sites on the domain are untouched)
  'strict-transport-security': 'max-age=15552000',
  'x-content-type-options': 'nosniff',
  'referrer-policy': 'no-referrer',
  'permissions-policy': 'camera=(), microphone=(), geolocation=(), payment=()',
  'x-frame-options': 'DENY'
};
function withSecurityHeaders(res) {
  const out = new Response(res.body, res);
  Object.keys(SECURITY_HEADERS).forEach(function (k) { out.headers.set(k, SECURITY_HEADERS[k]); });
  return out;
}

// Plain http gets sent to https (browsers label http pages "Not secure" and many school and office filters block them).
// Cloudflare tells us how the visitor really connected in the cf-visitor header. Local development stays on http.
function insecureRequest(request, url) {
  if (/^(localhost|127\.0\.0\.1|\[::1\])$/.test(url.hostname) || /\.localhost$/.test(url.hostname)) return false;
  return url.protocol === 'http:' || /"scheme"\s*:\s*"http"/.test(request.headers.get('cf-visitor') || '');
}

async function route(request, env, ctx) {
    const url = new URL(request.url);
    if (insecureRequest(request, url)) {
      url.protocol = 'https:';
      return new Response(null, { status: 301, headers: { location: url.toString(), 'cache-control': 'no-store' } });
    }

    if (url.pathname.startsWith("/api/")) {
      try {
        return await handleApi(request, env, url);
      } catch (e) {
        return json({ error: 'Something went wrong. Please try again.' }, 500);
      }
    }

    if (url.pathname === "/manifest.json") {
      return new Response(JSON.stringify(MANIFEST), {
        headers: {
          "content-type": "application/manifest+json;charset=UTF-8",
          "cache-control": "public, max-age=86400"
        }
      });
    }

    if (url.pathname === "/sw.js") {
      return new Response(SW, {
        headers: {
          "content-type": "application/javascript;charset=UTF-8",
          "cache-control": "public, max-age=0"
        }
      });
    }

    return new Response(HTML, {
      headers: {
        "content-type": "text/html;charset=UTF-8",
        "cache-control": "no-cache"
      }
    });
  }

export default {
  async fetch(request, env, ctx) {
    return withSecurityHeaders(await route(request, env, ctx));
  }
};
